using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Drawing;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class WaveTests {
  static int checks;static void Check(bool b,string text){checks++;if(!b)throw new Exception(text);}static void Near(double a,double b,string text){Check(Math.Abs(a-b)<1e-7*Math.Max(1,Math.Abs(b)),text+": "+a+" / "+b);}
  public static int Run(string folder){Directory.CreateDirectory(folder);try{using(var kernel=new CADKernel())foreach(int ratio in new[]{50,80,100}){var p=new WaveParameters{Ratio=ratio,Flat=false};Near(p.OutputRpm,-60.0/ratio,"reverse output rpm");Near(p.OutputTorque,.35*ratio*.7,"torque with user efficiency");Near(p.RequiredTorque,5.0/(ratio*.7),"required input torque");Check(p.FlexTeeth+2==p.RingTeeth,"two-tooth difference");var doc=p.Document();var r=kernel.Run(doc);Check(r.Bodies.Count==4&&r.Bodies.All(b=>b.Volume>0),"four valid non-empty CAD bodies "+ratio);string step=Path.Combine(folder,"Wave_"+ratio+".step");kernel.Run(doc,"export_step",step);doc.Save(Path.Combine(folder,"Wave_"+ratio+".cad.json"));var back=kernel.Run(CADDocument.ImportStep(File.ReadAllBytes(step),"wave"));Near(back.Bodies.Sum(b=>b.Volume),r.Bodies.Sum(b=>b.Volume),"STEP roundtrip volume "+ratio);var result=new Result{P=new Parameters{Kind=4},Model=r.Assembly(doc),Wave=p};var flex=result.Model.Parts.Single(b=>b.Id.EndsWith("_flex"));var motion=PartMotion.Bind(result,flex);var q=motion.At(2*Math.PI,0).Transform(new Point3D(10,0,0));Near(q.X,10*Math.Cos(-2*Math.PI/ratio),"flex output rotation X");Near(q.Y,10*Math.Sin(-2*Math.PI/ratio),"flex output rotation Y");var ring=result.Model.Parts.Single(b=>b.Id.EndsWith("_ring"));Check(!PartMotion.Bind(result,ring).Moving,"rigid ring fixed");var source=flex.MeshOverride;var zero=WaveMotion.Deform(source,p,0);Near((source.Points[0]-zero.Points[0]).Length,0,"zero animation matches source");var ninety=WaveMotion.Deform(source,p,Math.PI/2);Check(ninety.Points.Zip(source.Points,(a,b)=>(a-b).Length).Max()>.1,"elastic preview deforms rather than only rotates");using(var scene=new WpfScene()){scene.SetResult(result,false);scene.UpdatePose(Math.PI/2);Check(scene.Nodes.Single(n=>n.Part.Id==flex.Id).WavePhase==Math.PI/2,"scene updates cup deformation");scene.SavePng(Path.Combine(folder,"Wave_"+ratio+".png"),1100,800);}if(ratio==50){doc.Features[0].Values["Phase"]="90";var phase=kernel.Run(doc);Check(phase.Bodies.Count==4,"exact phase geometry rebuild");kernel.Run(doc,"export_step",Path.Combine(folder,"Wave_50_phase90.step"));kernel.Run(doc,"export_stl",Path.Combine(folder,"Wave_50.stl"));Check(new FileInfo(Path.Combine(folder,"Wave_50.stl")).Length>1000,"STL export");}}
   using(var form=new WaveReducerForm()){form.Show();var clock=System.Diagnostics.Stopwatch.StartNew();while(!form.TestReady&&clock.Elapsed.TotalSeconds<180){Application.DoEvents();Thread.Sleep(20);}Check(form.TestReady,"wave native UI built");using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(Path.Combine(folder,"wave-ui.png"));}form.Close();}File.WriteAllText(Path.Combine(folder,"wave-results.txt"),"PASS "+checks+" wave assertions: ratios, torque, exact STEP roundtrips, prescribed cup animation, STL and native UI.\r\nContact, elastic stress and load capacity are outside this concept model.",Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"wave-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
 }
}
